// Item reporting. Each fact is asked for once per distinct question, and cached for the rest of the call.

function distinctGroups(items) {
	const groups = [];
	for (const item of items) {
		if (!groups.includes(item.group)) {
			groups.push(item.group);
		}
	}
	return groups.sort();
}

export function convertAll(items, priceBook) {
	const rates = new Map();
	const rateFor = (currency) => {
		if (!rates.has(currency)) {
			rates.set(currency, priceBook.rateFor(currency));
		}
		return rates.get(currency);
	};
	return items.map((item) => ({
		id: item.id,
		baseMinor: Math.round((item.amountMinor * rateFor(item.currency)) / 100),
	}));
}

export function rankByGroup(items, scorer) {
	const scores = new Map();
	const scoreOf = (item) => {
		if (!scores.has(item.id)) {
			scores.set(item.id, scorer.scoreOf(item));
		}
		return scores.get(item.id);
	};
	return distinctGroups(items).map((group) => {
		const ranked = items
			.filter((item) => item.group === group)
			.slice()
			.sort((left, right) => scoreOf(right) - scoreOf(left) || left.id.localeCompare(right.id))
			.map((item) => item.id);
		return { group, ranked };
	});
}

export function groupReport(items, priceBook, scorer) {
	const rates = new Map();
	const rateFor = (currency) => {
		if (!rates.has(currency)) {
			rates.set(currency, priceBook.rateFor(currency));
		}
		return rates.get(currency);
	};
	const scores = new Map();
	const scoreOf = (item) => {
		if (!scores.has(item.id)) {
			scores.set(item.id, scorer.scoreOf(item));
		}
		return scores.get(item.id);
	};

	const groups = new Map();
	for (const item of items) {
		const current = groups.get(item.group) ?? { group: item.group, totalBaseMinor: 0, top: null, topScore: -1 };
		current.totalBaseMinor += Math.round((item.amountMinor * rateFor(item.currency)) / 100);
		const score = scoreOf(item);
		if (score > current.topScore || (score === current.topScore && item.id.localeCompare(current.top) < 0)) {
			current.top = item.id;
			current.topScore = score;
		}
		groups.set(item.group, current);
	}
	return [...groups.values()]
		.sort((left, right) => left.group.localeCompare(right.group))
		.map(({ group, totalBaseMinor, top }) => ({ group, totalBaseMinor, top }));
}
